tasks.model:
byte credits;

active proctype issuer()
{
  do
  :: credits++
  od
}

active proctype spender()
{
  do
  :: credits > 0 -> credits--
  od
}

int total;

active proctype worker()
{
  do
  :: total = total + 1
  unless { total > 3 -> break }
  od
}

byte a; byte b; byte c; byte d;

active proctype p1() { do :: a < 255 -> a++ :: a > 0 -> a-- od }
active proctype p2() { do :: b < 255 -> b++ :: b > 0 -> b-- od }
active proctype p3() { do :: c < 255 -> c++ :: c > 0 -> c-- od }
active proctype p4() { do :: d < 255 -> d++ :: d > 0 -> d-- od }

byte a; byte b; byte c; byte d;

active proctype p1() { do :: a < 255 -> a++ :: a > 0 -> a-- od }
active proctype p2() { do :: b < 255 -> b++ :: b > 0 -> b-- od }
active proctype p3() { do :: c < 255 -> c++ :: c > 0 -> c-- od }
active proctype p4() { do :: d < 255 -> d++ :: d > 0 -> d-- od }

bool want[2];
byte served;

active [2] proctype client()
{
  byte me = _pid;
  do
  :: want[me] = true;
     served = me;
     want[me] = false
  od
}
